import pandas as pd, numpy as np, warnings
warnings.filterwarnings('ignore')
R=pd.read_csv('validation/film_results.csv'); F=pd.read_csv('validation/films.csv').set_index('film'); C=pd.read_csv('validation/candidates.csv')
def arr(g):
    w=(g.edge_tp+g.edge_fp+g.edge_fn).to_numpy(float); return w, w*g.adj.to_numpy(float), g.division_tp.to_numpy(float), (g.division_tp+g.division_fp+g.division_fn).to_numpy(float)
def sc(a,m=None):
    w,wa,tp,c=a
    if m is not None: w,wa,tp,c=w[m],wa[m],tp[m],c[m]
    return wa.sum()/w.sum()+(0.1*tp.sum()/c.sum() if c.sum()>0 else 0.0)
def boot(a,b,n,B=4000,seed=1):
    rng=np.random.default_rng(seed); idx=rng.integers(0,len(a[0]),(B,n))
    def s(x):
        w,wa,tp,c=[v[idx].sum(1) for v in x]; return wa/w+np.where(c>0,0.1*tp/np.maximum(c,1),0)
    return s(b)-s(a)
def pair(lane,base,cand,short=False):
    gb=R[(R.lane==lane)&(R.candidate==base)].set_index('film'); gc=R[(R.lane==lane)&(R.candidate==cand)].set_index('film')
    fl=sorted(set(gb.index)&set(gc.index)); gb=gb.loc[fl]; gc=gc.loc[fl]; a=arr(gb); b=arr(gc); n=len(fl)
    d=sc(b)-sc(a); bd=boot(a,b,n)
    emb=gb.embryo.to_numpy(); grp=F.loc[fl,'group'].fillna('-').to_numpy()
    de='/'.join(f"{sc(b,emb==e)-sc(a,emb==e):+.4f}" if (emb==e).sum() else 'na' for e in ['6bba','44b6'])
    dg='/'.join(f"{sc(b,grp==g)-sc(a,grp==g):+.4f}" if (grp==g).sum() else 'na' for g in ['A36','B49','C29'])
    dadj=gc.adj.to_numpy()-gb.adj.to_numpy(); dfp=(gc.division_fp-gb.division_fp).to_numpy(); dtp=(gc.division_tp-gb.division_tp).to_numpy()
    inf=np.array([d-(sc(b,np.arange(n)!=i)-sc(a,np.arange(n)!=i)) for i in range(n)]); o=np.argsort(-np.abs(inf)); keep=np.ones(n,bool); keep[o[:2]]=False
    print(f"{lane[:11]:11s} {cand}-{base} n={n} d={d:+.5f} CI[{np.percentile(bd,2.5):+.4f},{np.percentile(bd,97.5):+.4f}] p+={np.mean(bd>0):.2f} sd={bd.std():.4f} div {int(a[2].sum())}/{int(gb.division_fp.sum())}/{int(gb.division_fn.sum())}->{int(b[2].sum())}/{int(gc.division_fp.sum())}/{int(gc.division_fn.sum())} adj+/-/0={int((dadj>1e-9).sum())}/{int((dadj<-1e-9).sum())}/{int((abs(dadj)<=1e-9).sum())} emb6/44={de} grpA/B/C={dg} changedDivFilms={int(((dfp!=0)|(dtp!=0)).sum())} dFP6/44={int(dfp[emb=='6bba'].sum())}/{int(dfp[emb=='44b6'].sum())} top2={inf[o[0]]:+.4f},{inf[o[1]]:+.4f} d_wo2={sc(b,keep)-sc(a,keep):+.5f}")
    return d
for c in ['FA','TP2','TAP','FAS','PR07']: pair('honest_oof','V12',c)
pair('honest_oof','FA','TP2')
for c in ['FA','TP2','TAP','FAS']: pair('honest_oofm','V12',c)
# selection grid
for lane in ['in_sample','honest_oof','honest_oofm']:
    base=arr(R[(R.lane==lane)&(R.candidate=='V12')].sort_values('film'))
    ds={c:sc(arr(g.sort_values('film')))-sc(base) for c,g in R[R.lane==lane].groupby('candidate')}
    s=pd.Series(ds).sort_values(ascending=False)
    print(lane,'k=',len(s),'top:',' '.join(f"{k}:{v:+.4f}" for k,v in s.head(7).items()),'| bottom:',' '.join(f"{k}:{v:+.4f}" for k,v in s.tail(3).items()))
print(C[C.lane=='honest_oof'][['candidate','match_type','source_file']].groupby(['source_file','match_type']).size().to_string())

